103	json OpenAIResponsesAgent::initial_input(const AgentRequest& request) const
104	{
105	    json input = json::array();
106	    for (const auto& message : request.conversation) {
107	        if (message.call_id.empty()) {
108	            input.push_back(json{{"role", message.role}, {"content", message.text}});
109	            continue;
110	        }
111	        // A call from an earlier turn, replayed for this stateless request.
112	        // Its call_id pairs it with its output. The item id the service gave
113	        // the call is not sent: with store:false it names nothing kept.
114	        input.push_back(json{{"type", "function_call"}, {"call_id", message.call_id}, {"name", message.tool},
115	                             {"arguments", message.arguments_json}});
116	        input.push_back(json{{"type", "function_call_output"}, {"call_id", message.call_id}, {"output", message.output_json}});
117	    }
118	    if (request.purpose == AgentRequest::Purpose::ConversationTitle)
119	        return input;
120	    // A turn the app started, after one of its own notes: nothing was said,
121	    // and an empty user message would read as the person saying nothing.
122	    if (request.user_text.empty() && request.attachments.empty() && !request.session.include_workspace)
123	        return input;
124	
125	    json content = json::array();
126	    std::ostringstream context;
127	    context << request.user_text;
128	    if (request.session.include_workspace)
129	        context << "\n\nAuthoritative JusPrin workspace context:\n" << workspace_json(request.workspace).dump();
130	    for (const auto& attachment : request.attachments) {
131	        context << "\nAttachment " << attachment.id << ": " << attachment.name << " [" << attachment.kind << "]";
132	        if (!attachment.summary.empty())
133	            context << " — " << attachment.summary;
134	        if (!attachment.text.empty())
135	            context << "\n<attachment id=\"" << attachment.id << "\">\n" << attachment.text << "\n</attachment>";
136	    }
137	    content.push_back(json{{"type", "input_text"}, {"text", context.str()}});
138	    for (const auto& attachment : request.attachments) {
139	        if (attachment.bytes.empty())
140	            continue;
141	        const std::string mime = attachment.mime.empty() ? "application/octet-stream" : attachment.mime;
142	        const std::string data_url = "data:" + mime + ";base64," + base64_encode(attachment.bytes);
143	        if (attachment.kind == "image")
